args.code:
const tabId = 343605414;

const allRoomDetails = await browserjs(tabId, async () => {
  // Let's find all distinct room sections/blocks
  // Each room block has a heading and a "See All Details" button
  const results = [];

  // Find all buttons that say "See All Details"
  const allButtons = Array.from(document.querySelectorAll('button')).filter(b => b.textContent.trim() === 'See All Details');

  // Note: there might be duplicate buttons if each lease option repeats or something, let's check how many unique rooms
  for (let i = 0; i < allButtons.length; i++) {
    const btn = allButtons[i];
    // Find room name above button
    let container = btn.closest('[class*="RoomCard"], [class*="room-card"]') || btn.parentElement;
    while (container && !container.querySelector('h3, h4')) {
      container = container.parentElement;
    }
    const heading = container ? container.querySelector('h3, h4')?.textContent?.trim() : `Room ${i}`;

    // Check if we already checked this heading
    if (results.some(r => r.heading === heading)) continue;

    // Click button
    btn.click();
    await new Promise(r => setTimeout(r, 200));

    const dialog = document.querySelector('[role="dialog"]');
    if (dialog) {
      const text = dialog.innerText;
      const isPrivateBath = text.toLowerCase().includes('private bathroom');
      const isSharedBath = text.toLowerCase().includes('shared bathroom');
      const priceMatch = text.match(/From\s*\$([0-9,]+)/i);
      results.push({
        heading,
        bathroom: isPrivateBath ? 'Private bathroom' : (isSharedBath ? 'Shared bathroom' : 'Unknown'),
        price: priceMatch ? `$${priceMatch[1]}` : null,
        rawText: text.slice(0, 300)
      });

      // Close dialog
      const closeBtn = dialog.querySelector('button[aria-label="Close"], button:has(svg)');
      if (closeBtn) closeBtn.click();
      else {
        const esc = new KeyboardEvent('keydown', { key: 'Escape', code: 'Escape', keyCode: 27, bubbles: true });
        document.dispatchEvent(esc);
      }
      await new Promise(r => setTimeout(r, 150));
    }
  }

  return results;
});

console.log(JSON.stringify(allRoomDetails, null, 2));

